import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.CxkNbRKf.js";const g=JSON.parse('{"title":"Bulk data access","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/bulk-data-access.md","filePath":"admin-guide/web-ui/bulk-data-access.md","lastUpdated":1786379412000}'),c={name:"admin-guide/web-ui/bulk-data-access.md"};function l(o,e,n,d,r,u){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="bulk-data-access" tabindex="-1">Bulk data access <a class="header-anchor" href="#bulk-data-access" aria-label="Permalink to &quot;Bulk data access&quot;">​</a></h1><p>Bulk data access allows administrators to group studies into collections that users can download as a package. This is useful when datasets are frequently requested together or belong to a related series.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Bulk data access list view showing available collections</em></p></div><h2 id="managing-bulk-access-collections" tabindex="-1">Managing bulk access collections <a class="header-anchor" href="#managing-bulk-access-collections" aria-label="Permalink to &quot;Managing bulk access collections&quot;">​</a></h2><p>Go to <strong>Studies → Bulk data access</strong> in the administrator menu.</p><p>The page lists all bulk access collections with the collection name, number of attached studies, and available actions.</p><h2 id="creating-a-collection" tabindex="-1">Creating a collection <a class="header-anchor" href="#creating-a-collection" aria-label="Permalink to &quot;Creating a collection&quot;">​</a></h2><ol><li>Click <strong>Add collection</strong>.</li><li>Enter a title and description for the collection.</li><li>Optionally set a weight to control the display order.</li><li>Click <strong>Save</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Create bulk access collection form</em></p></div><h2 id="attaching-studies" tabindex="-1">Attaching studies <a class="header-anchor" href="#attaching-studies" aria-label="Permalink to &quot;Attaching studies&quot;">​</a></h2><p>After creating a collection, attach studies to it:</p><ol><li>Open the collection from the list.</li><li>Click <strong>Attach studies</strong>.</li><li>Search for and select the studies to include.</li><li>Click <strong>Save</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Attach studies to bulk access collection</em></p></div><h2 id="editing-and-deleting" tabindex="-1">Editing and deleting <a class="header-anchor" href="#editing-and-deleting" aria-label="Permalink to &quot;Editing and deleting&quot;">​</a></h2><p>Use the <strong>Edit</strong> and <strong>Delete</strong> actions in the collection list to modify or remove a collection. Deleting a collection does not delete the studies — it only removes the bulk access grouping.</p><h2 id="user-facing-access" tabindex="-1">User-facing access <a class="header-anchor" href="#user-facing-access" aria-label="Permalink to &quot;User-facing access&quot;">​</a></h2><p>When a bulk access collection is published, users can download all attached studies as a package from the catalog&#39;s public interface.</p>',17)])])}const p=a(c,[["render",l]]);export{g as __pageData,p as default};
